const config = $('Set Workflow Config').first().json;

function formatDateIso(d) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Madrid',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(d);
  const y = parts.find(p => p.type === 'year').value;
  const m = parts.find(p => p.type === 'month').value;
  const day = parts.find(p => p.type === 'day').value;
  return y + '-' + m + '-' + day;
}

let rangeStart = '';
let rangeEnd = '';
let targetDateDesc = '';

if (config.test_mode && config.test_date_override && config.test_date_override.trim() !== '') {
  const testDate = config.test_date_override.trim();
  rangeStart = testDate + 'T00:00:00';
  rangeEnd = testDate + 'T23:59:59';
  targetDateDesc = testDate;
} else {
  const now = new Date();
  const dayOfWeek = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Europe/Madrid',
    weekday: 'short'
  }).format(now); // 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'

  if (dayOfWeek === 'Fri') {
    // Viernes: Avisamos de las citas del fin de semana y del Lunes completo
    const saturday = new Date(now.getTime() + 1 * 24 * 60 * 60 * 1000);
    const monday = new Date(now.getTime() + 3 * 24 * 60 * 60 * 1000);
    rangeStart = formatDateIso(saturday) + 'T00:00:00';
    rangeEnd = formatDateIso(monday) + 'T23:59:59';
    targetDateDesc = 'Fin de semana y Lunes (' + formatDateIso(monday) + ')';
  } else {
    // Lunes a Jueves: Citas del día siguiente
    const tomorrow = new Date(now.getTime() + 1 * 24 * 60 * 60 * 1000);
    const tomorrowIso = formatDateIso(tomorrow);
    rangeStart = tomorrowIso + 'T00:00:00';
    rangeEnd = tomorrowIso + 'T23:59:59';
    targetDateDesc = tomorrowIso;
  }
}

return [{
  json: {
    target_date: targetDateDesc,
    tomorrow_start: rangeStart,
    tomorrow_end: rangeEnd,
    is_test_mode: Boolean(config.test_mode),
    test_phone_override: config.test_phone_override || ''
  }
}];

const items = $input.all();
const config = $('Set Workflow Config').first().json;
const results = [];

function normalizePhone(rawPhone) {
  if (!rawPhone) return null;
  let clean = String(rawPhone).replace(/[^0-9]/g, '');
  if (clean.startsWith('0034')) {
    clean = clean.substring(2);
  }
  if (clean.startsWith('34') && clean.length === 11) {
    return clean;
  }
  if (clean.length === 9 && ['6', '7', '8', '9'].includes(clean.charAt(0))) {
    return '34' + clean;
  }
  if (clean.length >= 9 && clean.length <= 15) {
    return clean;
  }
  return null;
}

// Teléfono limpio de recepción para el enlace directo corto y oficial
const rawCenterPhone = config.center_contact_phone || '34684653227';
const cleanCenterPhone = String(rawCenterPhone).replace(/[^0-9]/g, '');
const waShortLink = 'https://wa.me/' + cleanCenterPhone;

for (const item of items) {
  const row = item.json;
  if (!row || !row.id) continue;

  const patient = row.patients || {};

  // Control Opt-Out: Si el paciente tiene los recordatorios desactivados, se omite
  if (patient.recibir_recordatorios_whatsapp === false) {
    continue;
  }

  const tutors = patient.patient_tutors || [];
  const t1 = tutors.find(t => t.order_num === 1) || tutors[0];

  // Prioridad teléfono: Tutor 1 -> Paciente raíz -> Vacío
  let rawPhone = t1 && t1.phone ? t1.phone : (patient.phone || '');
  if (config.test_mode && config.test_phone_override && config.test_phone_override.trim() !== '') {
    rawPhone = config.test_phone_override.trim();
  }
  const cleanPhone = normalizePhone(rawPhone);

  // Nombre del peque para el mensaje
  const patientFullName = row.patient_name || ((patient.first_name || '') + ' ' + (patient.last_name || '')).trim() || '';
  const patientFirstName = (patient.first_name || (row.patient_name ? row.patient_name.split(' ')[0] : '') || 'tu peque').trim();

  const startDate = new Date(row.start_time);
  const timeFormatted = startDate.toLocaleTimeString('es-ES', {
    timeZone: 'Europe/Madrid',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });

  const dateFormattedRaw = startDate.toLocaleDateString('es-ES', {
    timeZone: 'Europe/Madrid',
    weekday: 'long',
    day: 'numeric',
    month: 'long'
  });
  const dateFormatted = dateFormattedRaw.charAt(0).toUpperCase() + dateFormattedRaw.slice(1);

  const nombreTerapeuta = row.therapist_name || 'tu especialista';
  const tipoServicio = row.type || 'Sesión programada';

  // ¿Requiere enviar la cláusula RGPD informativa inicial (primer contacto)?
  const needsRgpd = !patient.whatsapp_rgpd_enviado;

  let rgpdText = '';
  if (needsRgpd) {
    if (config.test_mode) {
      rgpdText += '[CLÁUSULA RGPD INICIAL - PRUEBA] 📋\n\n';
    }
    rgpdText += '*Centro Infantil Proyecta, S.L. - Información de Protección de Datos*\n\n';
    rgpdText += 'Le informamos de que los datos personales facilitados en esta conversación serán tratados por Centro Infantil Proyecta, S.L. con la finalidad de atender sus consultas y gestionar las comunicaciones relacionadas con sus citas, incluido el envío de avisos y recordatorios.\n\n';
    rgpdText += 'Asimismo, puede ejercer sus derechos enviando un email a: centroproyectagijon@gmail.com, identificándose adecuadamente.\n\n';
    rgpdText += 'Para más información sobre el tratamiento de sus datos o sus derechos, puede consultar nuestra política de privacidad: https://centroproyecta.es/politica-de-privacidad';
  }

  // Redacción oficial y cercana del recordatorio de cita
  let reminderText = '';
  if (config.test_mode) {
    reminderText += '[MENSAJE DE PRUEBA] 🧪\n\n';
  }
  reminderText += '¡Hola familia! 👋🌟\n\n';
  reminderText += 'Te escribimos desde *Centro Proyecta* para recordarte la próxima cita de *' + patientFirstName + '*:\n\n';
  reminderText += '📅 *Fecha:* ' + dateFormatted + '\n';
  reminderText += '⏰ *Hora:* ' + timeFormatted + ' h\n';
  reminderText += '👩‍⚕️ *Especialista:* ' + nombreTerapeuta + '\n';
  reminderText += '🧩 *Servicio:* ' + tipoServicio + '\n';
  reminderText += '📍 *Lugar:* Centro Proyecta\n\n';
  reminderText += 'ℹ️ _Este es un canal de notificaciones automáticas y no recibe respuestas directas._\n\n';
  reminderText += 'Si necesitas modificar tu cita o no puedes asistir, por favor contáctanos por WhatsApp pulsando aquí:\n';
  reminderText += '👉 ' + waShortLink + ' (Recepción: 684 653 227)\n\n';
  reminderText += '¡Muchas gracias y nos vemos pronto! 😊✨';

  results.push({
    json: {
      cita_id: row.id,
      patient_id: patient.id || row.patient_id,
      patient_name: patientFullName || patientFirstName,
      recipient_name: 'Familia (' + patientFirstName + ')',
      therapist_name: nombreTerapeuta,
      service_type: tipoServicio,
      start_time: row.start_time,
      hora_cita: timeFormatted,
      fecha_cita: dateFormatted,
      raw_phone: rawPhone,
      phone: cleanPhone,
      valid_phone: Boolean(cleanPhone),
      needs_rgpd: Boolean(needsRgpd),
      rgpd_message: rgpdText,
      reminder_message: reminderText,
      is_test_mode: Boolean(config.test_mode)
    }
  });
}

return results;

